<script lang="ts">
 import {tick,onMount,untrack,type Snippet} from 'svelte';import {prefersReducedMotion} from 'svelte/motion';
 import {dateKey,emotions,type EmotionRecord} from '../domain';import {recordLabels} from '../companionship';
 let {records,open=$bindable(false),selected=$bindable(''),focusId='',reduced=false,children}=$props<{records:EmotionRecord[];open?:boolean;selected?:string;focusId?:string;reduced?:boolean;children:Snippet<[EmotionRecord]>}>();
 let cover:HTMLButtonElement,pages:HTMLDivElement,openedEntry=$state(''),limit=$state(20);
 let phase=$state<'closed'|'opening'|'open'|'closing'>('closed'),previousOpen=untrack(()=>open);
 let quiet=$derived(reduced||prefersReducedMotion.current);
 $effect(()=>{const target=open;if(quiet){phase=target?'open':'closed';previousOpen=target;}else if(target!==previousOpen){phase=target?'opening':'closing';previousOpen=target;}});
 let dates=$derived<string[]>(Array.from(new Set<string>(records.map(r=>dateKey(r.at)))).sort().reverse());
 let picked=$derived(dates.includes(selected)?selected:dates[0]||'');
 let dayRecords=$derived(records.filter(r=>dateKey(r.at)===picked));
 $effect(()=>{if(focusId){openedEntry=focusId;open=true;}});
 $effect(()=>{if(selected)open=true;});
 async function close(){open=false;await tick();cover?.focus({preventScroll:true});}
 async function openBook(){open=true;await tick();(pages?.querySelector<HTMLButtonElement>('nav button')||pages?.querySelector<HTMLButtonElement>('button'))?.focus({preventScroll:true});}
 function choose(day:string){limit=20;selected=day;openedEntry='';}
 function time(at:number){return new Date(at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});}
 onMount(()=>{const escape=(event:KeyboardEvent)=>{if(open&&event.key==='Escape'&&pages?.contains(document.activeElement)){event.preventDefault();event.stopPropagation();void close();}};document.addEventListener('keydown',escape);return()=>document.removeEventListener('keydown',escape);});
</script>
<div class="diary-heading"><div><h2>我的情绪日记</h2><p>把这段时光收成一本书，想看的时候再打开。</p></div><span>{records.length} 条</span></div>
<div class="diary-book" class:open class:quiet data-open={open} data-motion={phase} ontransitionend={event=>{if(event.target===event.currentTarget&&event.propertyName==='height')phase=open?'open':'closed';}}>
 <button class="diary-cover" type="button" bind:this={cover} aria-label="打开我的情绪日记" aria-expanded={open} aria-controls="emotion-diary-pages" tabindex={open?-1:0} onclick={openBook}><span class="diary-spine" aria-hidden="true"></span><span class="cover-stamp" aria-hidden="true">♡</span><strong>写给自己的日记</strong><span>{records.length?`${records.length} 次记录 · 最近 ${dates[0]}`:'还在等待第一段心事'}</span><span class="cover-action">翻开日记 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 4h6a3 3 0 0 1 3 3v14a5 5 0 0 0-4-2H4ZM20 4h-4a3 3 0 0 0-3 3M17 10l3 3-3 3"/></svg></span></button>
 <div class="diary-pages" id="emotion-diary-pages" bind:this={pages} inert={!open} aria-hidden={!open}>
  <aside class="diary-index"><div class="book-page-title"><strong>时光目录</strong><small>{dates.length} 天</small></div><nav aria-label="日记日期">{#each dates as day}<button type="button" class:chosen={picked===day} aria-pressed={picked===day} onclick={()=>choose(day)}><span>{day.slice(5).replace('-',' / ')}</span><small>{records.filter(r=>dateKey(r.at)===day).length} 条</small></button>{/each}</nav>{#if !dates.length}<p>下一次想记录时，<br/>这里会为你留一页。</p>{/if}<span class="index-footnote">每一种感受，<br/>都可以轻轻放在这里。</span></aside>
  <section class="diary-reading" aria-label="当天的情绪日记"><header><div><span>这一页，属于你</span><h3>{picked||'新的一页'}</h3></div><button class="text-button diary-close" type="button" aria-expanded={open} aria-controls="emotion-diary-pages" onclick={close}><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 4h6a3 3 0 0 1 3 3v14a5 5 0 0 0-4-2H4ZM20 4h-4a3 3 0 0 0-3 3m5 8-3-3 3-3"/></svg>合上日记</button></header><div class="diary-entries record-list">{#each dayRecords.slice(0,limit) as record (record.id)}<details class="diary-entry" open={openedEntry===record.id} ontoggle={event=>{if(event.currentTarget.open)openedEntry=record.id;else if(openedEntry===record.id)openedEntry='';}}><summary><time>{time(record.at)}</time><span><strong>{recordLabels(record).map(label=>emotions[label]).join(' · ')}</strong><small>{record.note||'给自己的心情留了一个位置。'}</small></span><i aria-hidden="true">＋</i></summary>{@render children(record)}</details>{/each}{#if dayRecords.length>limit}<button class="xy-btn" onclick={()=>limit+=20}>继续阅读当天记录</button>{/if}{#if !dayRecords.length}<div class="book-empty"><span aria-hidden="true">✧</span><p>这页还很安静。<br/>留下第一条记录后，再来翻翻吧。</p></div>{/if}</div><footer><span>慢慢读，也慢慢认识自己</span><small>{dates.length?dates.indexOf(picked)+1:0} / {dates.length}</small></footer></section>
 </div>
</div>
<style>
 .diary-heading{display:flex;align-items:start;justify-content:space-between;gap:20px;margin-bottom:18px}.diary-heading h2{margin:0!important}.diary-heading p{font-size:13px;color:var(--xy-secondary);margin-top:8px}.diary-heading>span{font-size:12px;color:var(--xy-secondary)}.diary-book{position:relative;height:220px;perspective:1600px;border-radius:10px;transition:height .38s cubic-bezier(.2,.7,.2,1);isolation:isolate}.diary-book.open{height:550px}.diary-cover{position:absolute;inset:0;z-index:2;display:grid;align-content:center;justify-items:center;gap:10px;width:100%;border:1px solid var(--xy-border);border-radius:8px;background:linear-gradient(120deg,color-mix(in srgb,var(--xy-selected) 75%,var(--xy-panel)),var(--xy-panel));box-shadow:inset 17px 0 0 color-mix(in srgb,var(--xy-accent) 25%,transparent),inset 23px 0 0 var(--xy-border),0 8px 20px #30234a0c;color:var(--xy-ink);transform-origin:left center;transition:transform .38s cubic-bezier(.2,.7,.2,1),opacity .22s ease-out;cursor:pointer}.cover-stamp{font-size:24px;color:var(--xy-accent)}.diary-cover strong{font-size:22px;letter-spacing:3px}.diary-cover>span:not(.cover-stamp){font-size:13px;color:var(--xy-secondary)}.open .diary-cover{transform:rotateY(-115deg);opacity:0;pointer-events:none}.diary-pages{position:absolute;inset:0;display:grid;grid-template-columns:220px minmax(0,1fr);background:var(--xy-panel);border:1px solid var(--xy-border);border-radius:9px;overflow:hidden;box-shadow:0 7px 22px #30234a10;opacity:0;transform:translateY(7px);transition:opacity .24s ease-out,transform .32s ease-out}.open .diary-pages{opacity:1;transform:none}.diary-index{display:flex;flex-direction:column;min-height:0;padding:22px;background:color-mix(in srgb,var(--xy-page) 65%,var(--xy-panel));border-right:1px solid var(--xy-border);box-shadow:inset -12px 0 15px #30234a05}.book-page-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.book-page-title strong{font-size:15px}.book-page-title small{font-size:12px;color:var(--xy-secondary)}.diary-index nav{display:grid;gap:7px;overflow:auto;scrollbar-width:thin}.diary-index nav button{display:flex;justify-content:space-between;align-items:center;min-height:42px;padding:9px 10px;border:1px solid transparent;border-radius:5px;background:transparent;color:var(--xy-secondary);font-variant-numeric:tabular-nums}.diary-index nav button.chosen{background:var(--xy-selected);border-color:var(--xy-border);color:var(--xy-ink)}.diary-index nav small{font-size:11px}.diary-index>p,.index-footnote{font-size:12px;line-height:1.9;color:var(--xy-secondary)}.index-footnote{margin-top:auto;padding-top:22px}.diary-reading{display:flex;flex-direction:column;min-height:0;min-width:0;padding:22px 26px;box-shadow:inset 10px 0 14px #30234a04}.diary-reading>header{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--xy-border);padding-bottom:14px}.diary-reading>header span{font-size:12px;color:var(--xy-secondary)}.diary-reading h3{font-size:19px;font-weight:600;margin:5px 0 0;font-variant-numeric:tabular-nums}.diary-reading .text-button{min-height:40px}:global(.xinyu-app .emotion-journey) .diary-entries{flex:1;min-height:0;overflow:auto!important;max-height:none;scrollbar-width:thin}.diary-entry{border-bottom:1px solid var(--xy-border)}.diary-entry>summary{display:flex;align-items:center;gap:14px;min-height:70px;padding:14px 3px;cursor:pointer;list-style:none}.diary-entry>summary time{font-size:12px;color:var(--xy-secondary);font-variant-numeric:tabular-nums}.diary-entry>summary>span{flex:1;min-width:0;display:grid;gap:5px}.diary-entry>summary strong{font-size:14px;font-weight:600}.diary-entry>summary small{font-size:12px;color:var(--xy-secondary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.diary-entry>summary i{font-style:normal;font-size:20px;color:var(--xy-accent)}.diary-entry[open]>summary i{rotate:45deg}.diary-reading footer{display:flex;justify-content:space-between;padding-top:15px;font-size:11px;color:var(--xy-secondary)}.book-empty{padding:50px 20px;text-align:center;color:var(--xy-secondary);font-size:14px;line-height:2}.book-empty>span{font-size:32px;color:var(--xy-accent)}.quiet,.quiet .diary-cover,.quiet .diary-pages{transition:none}.quiet.open .diary-cover{transform:none}
 /* A fixed-size cover turns at the spine while the page block unfolds behind it.
    Retaining the original DOM also retains in-progress correction fields on reversal. */
 .diary-book{height:248px;overflow:clip;perspective:1800px;transition:height .48s cubic-bezier(.2,.7,.2,1)}
 .diary-book.open{height:550px}
 .diary-cover{inset:0 auto auto 50%;width:clamp(300px,42%,380px);height:248px;transform:translateX(-50%) rotateY(0);transform-origin:left center;backface-visibility:hidden;transition:transform .48s cubic-bezier(.2,.7,.2,1),opacity .28s ease-out;box-shadow:inset 14px 0 0 color-mix(in srgb,var(--xy-accent) 24%,transparent),inset 20px 0 0 var(--xy-border),3px 4px 0 color-mix(in srgb,var(--xy-panel) 80%,var(--xy-border)),4px 5px 0 var(--xy-border),0 9px 24px #30234a12}
 .open .diary-cover{transform:translateX(-50%) rotateY(-108deg);opacity:0}
 .diary-pages{inset:0 0 auto;height:550px;transform:translateY(8px) scale(.99);transform-origin:50% 120px;opacity:0;transition:transform .48s cubic-bezier(.2,.7,.2,1),opacity .22s ease-out;box-shadow:0 7px 22px #30234a10,inset 0 -4px 0 color-mix(in srgb,var(--xy-border) 45%,var(--xy-panel))}
 .open .diary-pages{transform:none;opacity:1;transition-delay:0s,.07s}
 .diary-pages::after{content:'';position:absolute;left:207px;top:0;bottom:4px;width:27px;background:linear-gradient(90deg,transparent,#30234a0f 45%,#30234a17 50%,transparent);pointer-events:none;opacity:.5;transition:opacity .3s ease-out}.open .diary-pages::after{opacity:1}
 .diary-cover strong{font-size:21px;letter-spacing:2px;text-wrap:balance}
 .diary-cover:focus:not(:focus-visible){outline:none}.diary-cover:focus-visible{outline:3px solid var(--xy-accent);outline-offset:-5px}
 .quiet,.quiet .diary-cover,.quiet .diary-pages,.quiet .diary-pages::after{transition:none}.quiet.open .diary-cover{transform:translateX(-50%);opacity:0}
.diary-book{height:184px}.diary-cover{inset:0 auto auto 0;width:100%;height:184px;transform:none;padding:24px 170px 24px 78px;justify-items:start;text-align:left;transform-origin:left bottom}.cover-stamp{position:absolute;left:30px;top:66px;font-size:30px}.open .diary-cover{transform:translateY(-6px) rotateY(-6deg);opacity:0}.diary-cover .cover-action{position:absolute;right:28px;top:70px;display:flex;align-items:center;gap:8px;padding:9px 12px;font-size:14px;color:var(--xy-ink);border:1px solid var(--xy-border);border-radius:8px;background:var(--xy-selected)}.diary-close{display:flex;align-items:center;gap:7px;min-height:42px;padding:7px 12px;border:1px solid var(--xy-border);border-radius:8px;background:var(--xy-selected);color:var(--xy-ink)}.diary-close:active{scale:.96}.diary-reading{padding:20px}.diary-pages{grid-template-columns:170px minmax(0,1fr)}.diary-index{padding:20px 16px}.diary-pages::after{left:157px}.quiet.open .diary-cover{transform:none}@media(prefers-reduced-motion:reduce){.diary-close:active{scale:1}}</style>
